// F52 (k-155, L071): larmar för varje resurs i public/ som laddas från en annan värd
// (skript, stilmall, typsnitt, bild, ram, ljud, video), och kontrollerar att supabase-js ligger lokalt.
// Vanliga länkar och anrop till Supabase-projektets API räknas inte.
// AI-skapat (B-051). Generated by AI, Directed by MS.
const fs = require('fs'), path = require('path');

// Godkända undantag: { fil, adress, skal } – tom när F52 öppnas.
const TILLATNA = [];
// Sajtens egna värdar (samma Vercel-projekt) räknas inte som utomstående.
const EGNA = /^(https?:)?\/\/(www\.)?(luminusloom\.net|vretasound\.com)(\/|$)/i;

function alla(d) { return fs.readdirSync(d, { withFileTypes: true }).flatMap(e => e.isDirectory() ? alla(path.join(d, e.name)) : [path.join(d, e.name)]); }
const hoppaOver = f => /(^|\/)supabase\.js$|(^|\/)591\.supabase\.js$|\.min\.js$|(^|\/)vendor\//.test(f.split(path.sep).join('/'));

function sok(text, typ) {
  const fynd = [];
  const t = text.replace(/<!--[\s\S]*?-->/g, '');
  const ext = '(https?:)?//';
  const re = [];
  if (typ === 'html' || typ === 'js') {
    re.push(new RegExp('<(script|img|iframe|video|audio|source|embed|track)\\b[^>]*\\s(src|srcset)=["\']?(' + ext + '[^"\'\\s>]+)', 'gi'));
    // <link> som laddar något (stylesheet, icon, preload, preconnect, manifest …); canonical och alternate pekar bara ut sidan.
    re.push(new RegExp('<link\\b(?![^>]*\\brel=["\']?(canonical|alternate|me|author)\\b)[^>]*\\shref=["\']?(' + ext + '[^"\'\\s>]+)', 'gi'));
  }
  re.push(new RegExp('@import\\s+(url\\()?["\']?(' + ext + '[^"\')\\s;]+)', 'gi'));
  re.push(new RegExp('url\\(\\s*["\']?(' + ext + '[^"\')\\s]+)', 'gi'));
  if (typ === 'js' || typ === 'html') re.push(/["'`](https:\/\/(cdn\.[^"'`\s]+|fonts\.googleapis\.com[^"'`\s]*|fonts\.gstatic\.com[^"'`\s]*|unpkg\.com[^"'`\s]*|cdnjs\.cloudflare\.com[^"'`\s]*|cdn\.jsdelivr\.net[^"'`\s]*))/g);
  for (const r of re) for (const m of t.matchAll(r)) {
    const adr = m.slice(1).find(x => x && /^(https?:)?\/\//.test(x));
    if (adr && !EGNA.test(adr)) fynd.push(adr);
  }
  return [...new Set(fynd)];
}

const filer = alla('public').filter(f => /\.(html|js|css)$/.test(f) && !hoppaOver(f));
const fynd = [];
for (const f of filer) {
  const typ = f.endsWith('.css') ? 'css' : f.endsWith('.js') ? 'js' : 'html';
  for (const adr of sok(fs.readFileSync(f, 'utf8'), typ)) {
    if (!TILLATNA.some(t => t.fil === f && t.adress === adr)) fynd.push({ fil: f, adress: adr });
  }
}

const idx = fs.readFileSync('public/index.html', 'utf8');
const lib = fs.existsSync('public/js/supabase.js') ? fs.readFileSync('public/js/supabase.js', 'utf8') : '';
const lic = fs.existsSync('public/js/supabase.LICENSE.txt') ? fs.readFileSync('public/js/supabase.LICENSE.txt', 'utf8') : '';
const krav = {
  ingenJsdelivr: filer.every(f => !fs.readFileSync(f, 'utf8').includes('cdn.jsdelivr.net')),
  lokaltBibliotek: lib.length > 10240 && lib.includes('createClient') && fs.existsSync('public/js/591.supabase.js') && lic.includes('MIT'),
  taggPekarLokalt: idx.includes('<script src="/js/supabase.js"></script>') && !/<script[^>]+src="https?:/i.test(idx),
  ingaExternaResurser: fynd.length === 0,
  testetFangar: sok('<script src="https://cdn.jsdelivr.net/x.js"></script>', 'html').length === 1
    && sok('@import url(https://fonts.googleapis.com/css2);', 'css').length === 1
    && sok('<a href="https://vri.earth">vri.earth</a>', 'html').length === 0
    && sok('<link rel="canonical" href="https://example.org/">', 'html').length === 0
    && sok('<link rel="stylesheet" href="https://example.org/a.css">', 'html').length === 1,
};
const ok = Object.values(krav).every(Boolean);
console.log(JSON.stringify({ ...krav, fynd, ok }));
process.exit(ok ? 0 : 1);
